local _, WFI = ...
WFI.Data.add("quest", {
  [94007] = { "Domare la bestia", "Presentati a Quel'ana Quickgale, a Valanaar.", "Ora che hai acquisito una certa dimestichezza con le terre selvagge degli altipiani, credo sia giunto il momento che tu cerchi un compagno animale tutto tuo.\n\nVa' al porto di Valanaar, a sud-est, e parla con Quel'ana Quickgale. Ti istruirà nell'arte di addomesticare le bestie.", nil, nil, 0xecd97a9a, 0x87db1216, 0xab76e227, nil, nil, "...mm" },
  [94013] = { "Domare la bestia", "Usa la Taming Rod per addomesticare un Vuldren Alpha nelle Gustberry Lowlands. Esercita le tue capacità, poi riporta la Taming Rod a Quel'ana Quickgale, a Valanaar.", "Sei <tornato/tornata> in trionfo dopo aver addomesticato due bestie. Ora è il momento della tua ultima prova. I venti di Zephras sussurrano di sfide più grandi.\n\nPrendi questa Taming Rod e recati nelle Gustberry Lowlands. Lì addomestica un Vuldren Alpha e dimostra la tua maestria.\n\nCompleta questa lezione e sarai <pronto/pronta> a imparare le vie più profonde del cacciatore.", "Imparerai, {name}, e un giorno sarai {class} di grande valore.", "Eccellente, {name}! Impari davvero in fretta. Ora che conosci le basi, posso insegnarti a stringere un legame duraturo con un compagno animale.\n\nVa' con questa conoscenza e prospera. Sii {class} come Zephras Isle ha bisogno che tu sia.", 0xecd97a9a, 0xd6749188, 0x420fabee, 0xe5057f89, 0x5c64ed8c, "....." },
  [94050] = { "Addestrare la bestia", "Parla con Quel'dora Quickgale, a Valanaar.", "Ora hai il potere di addomesticare un animale, ma devi anche acquisire le capacità per addestrarlo. Per questo non c'è nessuno migliore di mia sorella, Quel'dora. Ti darà la capacità di addestrare il tuo nuovo animale.\n\nVa' con i venti, giovane {class}.", nil, "Vedo che sei {class} alle prime armi. Sì, posso concederti le capacità necessarie per addestrare e guidare il tuo animale. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda, {name}, rispetta sempre l'equilibrio e vivi con meraviglia la natura che ti circonda. Ora va'. Ci parleremo di nuovo, più avanti.", 0xdbeedc0e, 0xa8d2fa5d, 0x1f82d9d8, nil, 0xfbd746d0, "...m." },
  [94373] = { "Il richiamo della terra", "Porta 2 Frostmane Bear Pendants a Teo Hammerstorm, ad Anvilmar.", "Sì, è giunto il momento, giovane <sciamano/sciamana>. Sei <cresciuto/cresciuta> <robusto/robusta> e <saldo/salda>, come la pietra sotto i nostri stivali. Intraprendere il cammino dello sciamano dimostra che hai la saggezza della montagna, ancora prima di aver dato prova di te. Hai la tempra della pietra per percorrere il sentiero della terra.\n\nMa per guadagnarti il suo favore, devi affrontarla come si deve. A sud di qui, i troll Frostmane vivono in una grotta.\n\nPortami due delle collane che indossano, fatte con gli orsi Iceclaw. Poi parleremo ancora del tuo futuro.", "La pazienza, <ragazzo/ragazza>, è la virtù più bella della terra. Ha visto montagne sgretolarsi e fiumi scavare valli: lenta e testarda, come un vero membro della razza {race}. Ora la terra ti chiama, perché all'orizzonte si preparano guai. Torna con successo e sarai un passo più <vicino/vicina> a essere <completo/completa>.\n\nAltri potranno invidiare la tua saggezza, ma è un peso che spetta a loro portare.", "Ben fatto, <ragazzo/ragazza>. Hai dimostrato di essere <pronto/pronta>. La terra è il fondamento di tutte le cose. Forza, resistenza, pazienza. Ti proteggerà, ma solo se le mostrerai il giusto rispetto. Anche la pietra può spostarsi, se offesa. Impara le sue vie e diventerai più <saggio/saggia> della maggior parte della gente. Non dimenticare mai i segreti che condivide.\n\nOra ti preparerò una sapta: accettala e percorrerai il vero sentiero.", 0xe316c17f, 0xc897beee, 0x70173b78, 0xd804d26a, 0xb1f39df1, "....." },
  [94374] = { "Il richiamo della terra", nil, nil, nil, nil, 0xe316c17f, nil, nil, nil, nil, ".mmmm" },
  [94375] = { "Il richiamo della terra", "Porta il Rough Quartz a Teo Hammerstorm, ad Anvilmar.", "Prendi da me questo quarzo grezzo e portalo a Teo Hammerstorm come prova del nostro incontro. Creerà per te un totem, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che le dimensioni non contano, e che anche le cose più piccole possono durare più di molte altre.\n\nSii paziente, {name}. Resta forte. E cerca la saggezza. È ciò che la terra ti chiede. Alla fine diventerai tutt'uno con la terra: rispettala come lei rispetterà te.", "Ahh, sei <tornato/tornata>. Se hai la pietra, significa che la montagna ti ha davvero <scelto/scelta>. Ti darò il totem che ha promesso. Ma se sei <venuto/venuta> a mani vuote, sparisci! Il sentiero non è per chi dimentica la propria strada.", nil, 0xe316c17f, 0x1c898e3e, 0x1415c33d, 0xa9c8dad9, nil, "....m" },
  [94449] = { "Il richiamo del fuoco", "Trova Bruegs Kindleborn a Dun Morogh.", "È passato molto tempo dall'ultima volta che sei <stato/stata> <messo/messa> alla prova, {name}. Hai mostrato pazienza, sì, ma ora è tempo che tu impari il caos... la distruzione. Il richiamo del fuoco è forte e, se sei <pronto/pronta> a pagarne il prezzo, ti parlerà.\n\nCerca Bruegs Kindleborn, lontano a est tra le montagne. Vive in una grotta sopra il South Gate Outpost. Saprà se sei davvero <pronto/pronta>.", nil, nil, 0x53f3b76b, 0x15200cd4, 0xf3c2198f, nil, nil, "...mm" },
  [94465] = { "Il richiamo del fuoco", "Porta la Torch of the Dormant Flame a Braldir Ashmantle, a Loch Modan.", "Sì, hai la forza di portare il totem del fuoco, <ragazzo/ragazza>, ma la forza da sola non basta a renderti <pronto/pronta>.\n\nOltre la Valley of Kings, tra le rupi di Loch Modan, si trova un sentiero nascosto che porta a una delle nostre vette sacre. Lì Braldir Ashmantle custodisce lo Shrine of the Dormant Flame.\n\nPortagli questa torcia: mostra le tue intenzioni. Riportala accesa dal braciere del santuario e farò in modo che tu ti guadagni il totem come si deve.", nil, nil, 0x53f3b76b, 0xef8da8e8, 0x415200cc, nil, nil, "...mm" },
  [94466] = { "Il richiamo del fuoco", "Porta 1 Fire Tar e 1 Reagent Pouch a Braldir Ashmantle, a Loch Modan.", "Bah, non hai fatto tutta questa strada per sentire racconti, vero, {name}? Cerchi l'Eternal Flame e il totem del fuoco.\n\nPrima ti servirà una sapta per legare il tuo spirito alla fiamma.\n\nLa preparerò io, ma mi serviranno due cose: fire tar dai Tunnel Rat Geomancer nelle grotte dei kobold a nord, e una reagent pouch da uno Stonesplinter Seer che si aggira sulle colline meridionali. Un lavoro pericoloso, ma degno della fiamma.", nil, nil, 0x53f3b76b, 0x1ec23f46, 0x08842bb0, nil, nil, "...mm" },
  [94467] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [94468] = { "Il richiamo del fuoco", "Porta la Torch of Eternal Flame a Bruegs Kindleborn, a Dun Morogh.", "Con la torcia saldamente in mano, ti allontani dal braciere e guardi Loch Modan dall'alto. Senti un'emozione che ti tira lo spirito mentre il vento si alza e costringe la fiamma a danzare con violenza.\n\nTi incammini lungo il sentiero che riporta a Dun Morogh, in cerca di Bruegs Kindleborn.", nil, nil, 0x53f3b76b, 0x8fb8c297, 0x74b18970, nil, nil, "...mm" },
  [94494] = { "Il richiamo dell'acqua", "Trova Norric Lochthane a Loch Modan.", "È passato molto tempo dall'ultima volta che sei <stato/stata> <messo/messa> alla prova, {name}. Finora hai mostrato pazienza nei tuoi studi, ma è giunto il momento che tu impari la purezza dell'acqua.\n\nCerca Norric Lochthane a Loch Modan. Si trova lungo la riva nord-occidentale del lago, a sud dello Stonewrought Dam. Lo troverai lì, nella sua capanna scavata nella terra. Buona fortuna, {name}.", nil, nil, 0x1f0e11aa, 0xa614e79c, 0xf11bb23d, nil, nil, "...mm" },
  [94495] = { "Il richiamo dell'acqua", "Trova Hervdana Saegrund nelle Wetlands.", "Se c'è una verità che devi imparare sull'acqua, è questa: l'acqua significa rinascita. Scava la pietra, lava la sporcizia e guarisce chi è stanco, ma solo quando è pura. Contaminala, e rovinerà tutto ciò che tocca.\n\nSe cerchi la water sapta, trova Hervdana Saegrund nelle Wetlands. La sua famiglia vive in una grotta sotto le cascate meridionali.\n\nAvanti, allora, non lasciare che il fiume ti superi.", nil, nil, 0x1f0e11aa, 0xadc7f213, 0xadd95e2e, nil, nil, "...mm" },
  [94497] = { "Il richiamo dell'acqua", "Riempi l'Empty Brown Waterskin ai piedi delle cascate sotto la grotta di Hervdana e riportalo a lei, nelle Wetlands.", "Ah, quindi sei <venuto/venuta> a cercare la sapta, eh? Bene allora, ascolta attentamente, cara anima. Per trovare la comprensione e guadagnarti la sapta, devi cercare l'acqua nelle sue varie forme. Mentre raccogli i campioni, tieni gli occhi aperti. Osserva le bestie che la custodiscono, la terra che nutre e come cambia le vite.\n\nCominceremo con qualcosa di semplice: riempi questo otre ai piedi delle cascate, dove l'acqua dolce incontra quella salmastra. Va' ora, e <attento/attenta> alla palude.", nil, nil, 0x1f0e11aa, 0xa3d8f378, 0x4ed51e9b, nil, nil, "...mm" },
  [94499] = { "Il richiamo dell'acqua", "Riempi l'Empty Red Waterskin alle Stonewatch Falls, vicino ai Nightcrawler Murloc, e torna da Hervdana Saegrund, nelle Wetlands.", "Sì, Redridge beve a lungo dal Lake Everstill, ma quando le acque precipitano giù per le Stonewatch Falls qualcosa vi è penetrato. I murloc laggiù sono bruti grossi e deformi. Non come quelli che trovi qui o nel Loch. Per fortuna degli abitanti restano ai piedi delle cascate.\n\nPortami un campione. Ho in mente di scoprire se è magia, veleno o qualcosa di peggio a contaminare le acque vicino a quel vecchio forte.", nil, nil, 0x1f0e11aa, 0x6ccca7b4, 0xa2cb5a4a, nil, nil, "...mm" },
  [94500] = { "Il richiamo dell'acqua", "Riempi l'Unfilled Blue Waterskin nelle acque di Astranaar, ad Ashenvale, e torna da Hervdana Saegrund, nelle Wetlands.", "Prendi questo otre e addentrati nell'ombra smeraldina di Ashenvale. Astranaar riposa cullata da acque non toccate dalla corruzione. Rovine disseminano il fondo del lago, a testimonianza di un'era passata. Riporta un campione dal lago. Acqua pura, antica e forse incantata.\n\nÈ l'ultimo liquido che mi serve prima di rimandarti da Norric.\n\nPrendi la nave da Menethil per Auberdine. Durante la traversata fa scalo a Southshore.\n\nE sta' in guardia... la foresta ha occhi, e non sbattono le palpebre.", nil, nil, 0x1f0e11aa, 0x76aef756, 0xc7e05766, nil, nil, "...mm" },
  [94501] = { "Il richiamo dell'acqua", "Porta la Vial of Purest Water a Norric Lochthane, a Loch Modan.", "Norric avrà un ultimo compito per te prima di ricompensarti con i riti del totem dell'acqua. La fiala d'acqua che ti ho dato è necessaria per quel compito, qualunque sia. Ora va' a cercarlo. Ci incontreremo di nuovo un giorno.", nil, nil, 0x1f0e11aa, 0x0d508544, 0x58506c33, nil, nil, "...mm" },
  [94502] = { "Il richiamo dell'acqua", "Bevi la Water Sapta e purifica la corruzione allo Stendel's Pond, a Westfall.\r\nQuando hai finito, torna da Norric a Loch Modan.", "A Westfall, fuori da Moonbrook, si trova lo Stendel's Pond. Un tempo era una fonte pura, ora toccata da forze oscure. Gli spiriti di quel luogo sono ammutoliti.\n\nDevi bere la water sapta, poi affrontare la corruzione che insozza le acque. Prendi i suoi bracciali e le ultime gocce della pozione di Hervdana, poi ponili sul santuario. Questo richiamerà uno spirito, puro e sincero. Parla con lui e impara ciò che puoi.\n\nPortami la prova che l'impresa è compiuta e ti concederò il totem.", nil, nil, 0x1f0e11aa, 0x3dec7b07, 0x1215dd1a, nil, nil, "...mm" },
  [94503] = { "Il richiamo dell'acqua", "Parla con la Minor Manifestation of Water, a Westfall.", "La luce esplode mentre l'ultima parola lascia le tue labbra. Il sibilo dell'acqua che si trasforma in vapore svanisce nel silenzio, e i tuoi sensi vacillano mentre gli spiriti corrotti intorno a te si dissolvono, la loro essenza dispersa come cenere nel vento.", nil, nil, 0x1f0e11aa, 0x2cab5030, 0x31813519, nil, nil, "...mm" },
  [94505] = { "Il richiamo dell'acqua", "Porta lo Shard of Water a Norric Lochthane, a Loch Modan.", "Prendi frammento. Prendi frammento e dai vita.\n\nDai vita e capisci. Capisci acqua è vita... corruzione ferma vita.\n\nTu proteggi e dai vita con potere dell'acqua.", nil, nil, 0x1f0e11aa, 0x038a8a5c, 0x1bc4c72c, nil, nil, "...mm" },
  [94774] = { nil, "Parla con High Priestess Laurena, a Stormwind.", nil, nil, nil, nil, 0x8de762b6, nil, nil, nil, "m.mmm" },
  [94775] = { nil, "Parla con High Priestess Laurena, a Stormwind.", nil, nil, nil, nil, 0x8de762b6, nil, nil, nil, "m.mmm" },
  [94776] = { nil, "Parla con High Priestess Laurena, a Stormwind.", nil, nil, nil, nil, 0x8de762b6, nil, nil, nil, "m.mmm" },
  [94777] = { nil, "Parla con High Priestess Laurena, a Stormwind.", nil, nil, nil, nil, 0x8de762b6, nil, nil, nil, "m.mmm" },
  [94778] = { nil, "Parla con High Priestess Laurena, a Stormwind.", nil, nil, nil, nil, 0x8de762b6, nil, nil, nil, "m.mmm" },
  [94779] = { nil, "Parla con High Priestess Laurena, a Stormwind.", nil, nil, nil, nil, 0x8de762b6, nil, nil, nil, "m.mmm" },
  [94792] = { "Domare la bestia", "Usa la Taming Rod per addomesticare un Rockhide Boar. Esercita le tue capacità, poi riporta la Taming Rod a Josephine Carson.", "Molti cacciatori preferiscono viaggiare con compagni animali. Con una bestia al tuo fianco, scoprirai di poter sopravvivere anche nelle circostanze più pericolose. Come si dice, tutto è più facile con un amico. Tuttavia, ottenere un compagno animale è qualcosa da fare con cura. L'equilibrio della natura è delicato e va sempre rispettato.\n\nPorta questa Taming Rod con te nella foresta. Con essa potrai addomesticare un Rockhide Boar e mettere in pratica le tue capacità di <cacciatore/cacciatrice>.", "Imparerai, {name}, e un giorno sarai {class} di grande valore.", "Eccellente, {name}! Impari davvero in fretta.", 0xecd97a9a, 0x19efabbc, 0x69a91737, 0xe5057f89, 0x7f1a8496, "....." },
  [94793] = { "Addestrare la bestia", "Parla con Isaac Chan, a Goldshire.", "Ora hai il potere di addomesticare un animale, ma devi anche acquisire le capacità per addestrarlo. Per questo non c'è nessuno migliore di Isaac Chan, uomo dei boschi da una vita. Ti darà la capacità di addestrare il tuo nuovo animale.\n\nVa' con i venti, giovane {class}.", nil, "Vedo che sei {class} alle prime armi. Sì, posso concederti le capacità necessarie per addestrare e guidare il tuo animale. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda, {name}, rispetta sempre l'equilibrio e vivi con meraviglia la natura che ti circonda. Ora va'. Ci parleremo di nuovo, più avanti.", 0xdbeedc0e, 0xf8c4ebf2, 0x4bc880b0, nil, 0xfbd746d0, "...m." },
  [94817] = { "Lampo sconcertante", nil, nil, nil, nil, 0xd8782324, nil, nil, nil, nil, ".mmmm" },
  [94818] = { "Piano di riserva", nil, nil, nil, nil, 0x584b30b7, nil, nil, nil, nil, ".mmmm" },
  [94819] = { "Piano di riserva", "Parla con l'High Priestess Mims, a Ironforge.", "{name}, la tua High Priestess Mims vorrebbe riceverti a Ironforge. Affrettati, <mio/mia> <ingegnoso/ingegnosa> <amico/amica>: la tua prossima prova si avvicina rapidamente. Anche se vorrei poter assistere ai riti speciali della tua razza, il mio posto è qui. Ma che la Luce ti accompagni nei tuoi viaggi. Mims dovrebbe essere ancora nel Mystic Ward quando arriverai in città. Ti starà aspettando.", nil, nil, 0x584b30b7, 0x656c5f67, 0xf8b55805, nil, nil, "...mm" },
  [94820] = { "Piano di riserva", "Parla con l'High Priestess Mims, a Ironforge.", "La tua razza è così ingegnosa, {name}. Siamo fieri di chiamarvi alleati. E a ogni tramonto, tu e la tua gente vi avvicinate a riconquistare la vostra città, ma con il peso di proteggere le vostre famiglie in esilio. Quel desiderio di casa deve pesarti molto.\n\nPoco fa è arrivata una notizia da Ironforge. Chiedeva che tu tornassi lì a parlare con l'High Priestess Mims, nel Mystic Ward. Non la farei aspettare. Che Elune guidi i tuoi viaggi.", nil, nil, 0x584b30b7, 0x656c5f67, 0xfc0c8df4, nil, nil, "...mm" },
  [94821] = { "Lampo sconcertante", "Parla con l'High Priestess Mims, a Ironforge.", "Un sacerdote ha visitato di recente le nostre sale in cerca di te, {race}. Ha detto che era in missione per trovarti e che dovresti tornare alla Hall of Mysteries di Ironforge il prima possibile. Quando arrivi, cerca l'High Priestess Mims: ti dirà di più.\n\nChe la Luce sia con te, {name}.", nil, nil, 0xd8782324, 0x656c5f67, 0xb61e2669, nil, nil, "...mm" },
  [94822] = { "Lampo sconcertante", "Parla con l'High Priestess Mims, a Ironforge.", "Hai attirato l'attenzione dei nostri superiori, {name}. Ti chiedono di recarti alla Hall of Mysteries di Ironforge il prima possibile. A quanto pare ritengono che tu abbia già dato prova di te e che sia <pronto/pronta> a proseguire l'addestramento. Quando arrivi, cerca l'High Priestess Mims. Saprà guidarti oltre. Buona fortuna, e che la Luce sia con te.", nil, nil, 0xd8782324, 0x656c5f67, 0xf8811e2d, nil, nil, "...mm" },
  [94823] = { "Lampo sconcertante", "Parla con l'High Priestess Mims, a Ironforge.", "Che Elune ti benedica, {race}. Spero che la tua Luce ti trovi e ti protegga bene oggi.\n\nUno dei tuoi sacerdoti è passato di qui non molto tempo fa a cercarti. Ha detto che dovresti tornare alla Hall of Mysteries il prima possibile per parlare con l'High Priestess Mims. Sembra che tu abbia fatto bene, per attirare tanta attenzione. Non resterei qui troppo a lungo: la tua gente ha bisogno di te.", nil, nil, 0xd8782324, 0x656c5f67, 0xf4f34293, nil, nil, "...mm" },
  [94824] = { "Lampo sconcertante", "Parla con l'High Priestess Mims, a Ironforge.", "È ora che tu vada a Ironforge, {name}. L'High Priestess Mims, nella Hall of Mysteries, ti ordina di andare a parlarle. Dev'essere qualcosa di molto buono o di molto brutto se l'High Priestess ti vuole lì di persona, ma immagino che tu abbia fatto solo bene e che sia una buona cosa che voglia parlarti.\n\nMa non perdere troppo tempo da queste parti. Io ci andrei appena possibile.", nil, nil, 0xd8782324, 0x656c5f67, 0x68f292b0, nil, nil, "...mm" },
  [94825] = { "Lampo sconcertante", "Parla con l'High Priestess Mims, a Ironforge.", "Poco fa uno dei tuoi sacerdoti è passato di qui a cercarti, {race}. Ha detto che, se ti avessi visto, avrei dovuto indirizzarti verso la Hall of Mysteries. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Il suo atteggiamento sembrava positivo... come se fossero buone notizie. Al tuo posto non ci metterei troppo ad arrivarci.\n\nChe Elune sia con te, {race}.", nil, nil, 0xd8782324, 0x656c5f67, 0xa819c88b, nil, nil, "...mm" },
  [94826] = { "Lampo sconcertante", "Parla con l'High Priestess Mims, a Ironforge.", "Sia lodata Elune, e la tua Luce, {name}.\n\nPiù o meno in questo periodo molti del nostro ordine apprendono capacità che riflettono la loro fede in Elune. Se non sbaglio, credo che lo stesso valga anche per il tuo ordine.\n\nQuando avrai concluso i tuoi affari a Darnassus, cercherei la tua High Priestess per un ulteriore addestramento.", nil, nil, 0xd8782324, 0x656c5f67, 0x560c66c6, nil, nil, "...mm" },
  [94863] = { "Domare la bestia", "Usa la Taming Rod per addomesticare un Gray Forest Wolf. Esercita le tue capacità, poi riporta la Taming Rod a Josephine Carson.", "Hai già imparato ad addomesticare un cinghiale. Ora è il momento della prossima lezione. La foresta custodisce compagni più feroci e, con cura, puoi guadagnarti la loro fiducia.\n\nPrendi questa Taming Rod e cerca un Gray Forest Wolf. Ricorda, l'equilibrio della natura va rispettato. Dimostra ancora una volta la tua abilità di <cacciatore/cacciatrice>.", "Con l'apprendimento, {name}, arriva la maestria.", "Ben fatto, {name}! Sei proprio in sintonia con la bestia.", 0xecd97a9a, 0x18dda32c, 0x213604b0, 0x968b687d, 0xee58c591, "....." },
  [94864] = { "Domare la bestia", "Usa la Taming Rod per addomesticare uno Young Forest Bear. Esercita le tue capacità, poi riporta la Taming Rod a Josephine Carson.", "Hai dato prova di te addomesticando un cinghiale e un lupo. Ora è il momento della tua sfida finale. L'equilibrio di Elwynn dipende da rispetto e abilità. Prendi questa Taming Rod e cerca uno Young Forest Bear. Dimostra di saper guadagnare la fiducia anche del più possente dei compagni.\n\nCompletare questa lezione approfondirà la tua sintonia con le bestie.", "Va', {name}, e addomestica la più possente delle bestie di Elwynn.", "La forza bruta della foresta. Coraggioso lavoro, {name}!", 0xecd97a9a, 0x4d82c2d9, 0x1a8183ea, 0x62dcf008, 0x40ad2d6e, "....." },
  [94872] = { "Comprare l'amicizia: Magram", "Porta il Totem Tote al Magram Quartermaster, al Magram Village di Desolace, per aumentare notevolmente la tua reputazione con quel clan. Devi avere almeno la reputazione Neutral con i Magram Clan Centaur.", "I feroci Magram stanno senza dubbio vincendo la guerra per i territori in questo momento. Anche se possiamo essere tutti grati che gli scontri non siano scoppiati troppo spesso nel deserto, ogni giorno il loro villaggio, appena a est, si ingrandisce un po'; i loro soldati diventano un po' più audaci.\n\nMi preoccupano molto le conseguenze di un clan Magram senza freni, ma non posso negare il loro potenziale come alleati.\n\nSe vuoi guadagnarti la loro fiducia, offri questo sacco di totem al loro furiere, ma fa' attenzione.", nil, nil, 0xf5fd14ba, 0x66df78e4, 0x4c0d5c32, nil, nil, "...mm" },
  [94873] = { "Comprare l'amicizia: Gelkis", "Porta il Totem Tote al Gelkis Quartermaster, al Gelkis Village di Desolace, per aumentare notevolmente la tua reputazione con quel clan. Devi avere almeno la reputazione Neutral con i Gelkis Clan Centaur.", "Entrambi i clan di centauri dominanti potrebbero essere buoni alleati, ma dovrei metterti in guardia riguardo ai Gelkis.\n\nHo informazioni affidabili secondo cui, tra Magram e Gelkis, questi ultimi stanno decisamente perdendo. Questo potrebbe tornare a nostro vantaggio: la disperazione potrebbe spingere quel clan isolato ad aprirsi all'aiuto esterno.\n\nHo preparato una borsa di totem da portare al loro furiere, ammesso che ne abbiano uno, al Gelkis Village. Potrebbe giocare a nostro favore.", nil, nil, 0x57c3db29, 0x68c32afb, 0x03629ec5, nil, nil, "...mm" },
  [94911] = { "Figlio della natura", nil, nil, nil, nil, 0xb806d7b4, nil, nil, nil, nil, ".mmmm" },
  [94912] = { "Figlio della natura", "Parla con Sheldras Moontree, a Stormwind.", "Salute, giovane {class}.\n\nHai sentito parlare del Cenarion Circle? Immagino di no. È un antico ordine di naturalisti e di praticanti delle arti druidiche, proprio come te. Nella città di Stormwind troverai un elfo della notte di nome Sheldras Moontree. Ti insegnerà come raggiungere la roccaforte del Cenarion Circle su Kalimdor, un luogo chiamato Moonglade.\n\nVa' ora. Hai molto da imparare, se vuoi salvare la tua casa.", nil, nil, 0xb806d7b4, 0x59f95b86, 0xfd0dcca7, nil, nil, "...mm" },
  [94913] = { nil, "Usa l'incantesimo \"Teleport: Moonglade\" per andare a Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.", "Tutti i druidi sono i benvenuti nelle terre sacre di Moonglade. Il Keeper Remulos, guardiano di Moonglade, veglia su tutti i druidi che vi riposano. Ti insegnerò l'incantesimo che ti permette di trasportarti lì. Lancialo ogni volta che cerchi la conoscenza o il conforto di Moonglade.\n\nQuanto alla tua prima lezione qui su Azeroth, recati a Moonglade e parla con Dendrite Starblaze, a Nighthaven, del cammino che hai intrapreso. Buona fortuna, giovane <druido/druida>.", nil, "Ah, vedo che hai già padroneggiato la forma dell'orso. Bene, bene. Sei sulla buona strada, giovane {class}.", nil, 0xf8085429, 0x89074bce, nil, 0x0e12a96b, "m..m." },
  [94914] = { nil, "Usa l'incantesimo \"Teleport: Moonglade\" per andare a Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.", "Tutti i druidi sono i benvenuti nelle terre sacre di Moonglade. Il Keeper Remulos, guardiano di Moonglade, veglia su tutti i druidi che vi riposano. Ti insegnerò l'incantesimo che ti permette di trasportarti lì. Lancialo ogni volta che cerchi la conoscenza o il conforto di Moonglade.\n\nQuanto alla tua prima lezione qui su Azeroth, recati a Moonglade e parla con Dendrite Starblaze, a Nighthaven, del cammino che hai intrapreso. Buona fortuna, giovane <druido/druida>.", nil, nil, nil, 0xf8085429, 0x89074bce, nil, nil, "m..mm" },
  [94947] = { "<Benvenuto/Benvenuta> su Azeroth", "Prendi lo Skyborne Portal per Stormwind e fai rapporto a Bolvar Fordragon, nello Stormwind Keep.", "Quaggiù il mondo è grande, e la nostra gente deve cominciare a diramarsi per esplorarlo. È qui che entri in gioco tu.\n\nIl Kirin Tor fa parte di un'\"Alliance\" di nazioni affini. Il cuore di fatto di questa alleanza è la città di Stormwind, a sud. Elaadrin mi ha chiesto di trovare qualcuno che vada a Stormwind a incontrare il lord reggente, un umano di nome Bolvar Fordragon.\n\nQuando sarai <pronto/pronta>, i maghi del Kirin Tor hanno allestito un portale speciale che l'High Order può usare per raggiungere Stormwind.", nil, "Ben <trovato/trovata>, {class}. Sono Bolvar Fordragon, reggente del trono di Stormwind.\n\nUn messaggero del Kirin Tor mi ha detto di aspettarmi membri dell'High Order, ed eccoti qui. È passato del tempo dall'ultima volta che un alto elfo è stato in questa sala del trono, ma sono lieto di accoglierti ora come ospite.\n\nA nome del re ti do il benvenuto a Stormwind e ti concedo di viaggiare liberamente per le terre dell'Alliance. <Benvenuto/Benvenuta> su Azeroth, {race}.", 0x2f003d6f, 0x9e17660a, 0xc4f3c12d, nil, 0x6e9dee83, "...m." },
  [94978] = { "Domare la bestia", "Usa la Taming Rod per addomesticare un Windsong Crawler che si trova vicino agli specchi d'acqua. \r\nEsercita le tue capacità, poi riporta la Taming Rod a Quel'ana Quickgale, a Valanaar.", "Ogni cacciatore comincia imparando il legame tra bestia e padrone. Questa è la tua prima sfida. Col tempo addomesticherai creature di ogni angolo del mondo, ma per ora comincia con i nostri fiumi e laghi su Zephras.\n\nPrendi questa Taming Rod e cerca un Windsong Crawler.\n\nDimostra di saper guadagnare la sua fiducia e comincia il tuo cammino verso la vera maestria.", "Imparerai, {name}, e un giorno sarai {class} di grande valore.", "Ben addomesticato, {name}! Stai già diventando abile.", 0xecd97a9a, 0xc2ec4aaf, 0x97c66def, 0xe5057f89, 0x23710c4e, "....." },
  [94979] = { "Domare la bestia", "Usa la Taming Rod per addomesticare un Ornery Galestrider nelle Gustberry Lowlands. \r\nEsercita le tue capacità, poi riporta la Taming Rod a Quel'ana Quickgale, a Valanaar.", "Hai dimostrato di saper addomesticare il crawler del fiume. Ora è il momento di mettere alla prova la tua abilità in campo aperto. Le pianure di Zephras risuonano delle grida del galestrider, un cacciatore alato e fiero che corre come il vento.\n\nPrendi questa Taming Rod e cercane uno. Recati nelle pianure basse e guadagnati la sua fiducia.\n\nDimostra di essere <pronto/pronta> per le prove che ti attendono.", "Imparerai, {name}, e un giorno sarai {class} di grande valore.", "Sei già <tornato/tornata>! Velocità notevole, {name}!", 0xecd97a9a, 0x116b4c2f, 0x1cb8bfe1, 0xe5057f89, 0x599c5b8f, "....." },
})
